controls+=group('5. Буровой парк',[('drillPct','Доля массы, требующая бурения, %',80,0,100),('bench','Высота уступа, м',10,1,30),('burden','Линия сопротивления, м',3.5,.5,15),('spacing','Расстояние между скважинами, м',4,.5,20),('sub','Перебур, м',1,0,5),('rop','Чистая скорость бурения, м/ч',25,.1,200),('setup','Перестановка / вспомогательные операции, мин/скв.',5,0,120),('diameter','Диаметр скважин, мм (для задания)',115,50,400)],'Вертикальные скважины: объём блока на скважину = ЛСП × шаг × высота уступа. Диаметр фиксируется в задании и не подбирает сетку. Граничные скважины, наклон, взрывчатые вещества, перебур и безопасность БВР должны быть обоснованы отдельным проектом.')
